var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return main.get_tree().root.get_node("StratagemDialog/Content/Header").text.to_lower().contains("charge phase")

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
var roll = {}
for d in H.phase().dice_log:
	if typeof(d) == TYPE_DICTIONARY and str(d.get("source", "")) == "SELFLESS SERVICE":
		roll = d
print("[cus11e selfless] roll ", roll)
return not roll.is_empty() and int(roll.get("total", 99)) <= 6 and not bool(roll.get("charge_failed", true))

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return str(H.phase().heroic_intervention_unit_id)

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.phase().heroic_intervention_pending_charge.get("targets", [])

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.log_count("Used SELFLESS SERVICE")

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
var roll = {}
for d in H.phase().dice_log:
	if typeof(d) == TYPE_DICTIONARY and str(d.get("source", "")) == "SELFLESS SERVICE":
		roll = d
var mv: Dictionary = load("res://scripts/AIDecisionMaker.gd")._compute_charge_move(GameState.create_snapshot(), "U_WITCHSEEKERS_A", int(roll.total), ["U_GRETCHIN_C"], 2, "APPLY_HEROIC_INTERVENTION_MOVE")
mv["player"] = 2
var r = H.phase().execute_action(mv)
print("[cus11e selfless] move ", r.get("success", false), " ", r.get("error", ""))
return r.get("success", false)

